    const { name, value } = event.target;
    setForm({
      ...form,
      [name]: value
    });
  };

  return (
    <form>
      <input 
        name="nome"
        value={form.nome}
        onChange={handleChange}
      />
      <input 
        name="email"
        type="email"
        value={form.email}
        onChange={handleChange}
      />
      <input 
        name="senha"
        type="password"
        value={form.senha}
        onChange={handleChange}
      />
    </form>
  );
}
``` 

